export const DEFAULT_SKINS = Object.freeze(Object.fromEntries(SKINS.filter(skin => skin.isDefault).map(skin => [skin.weapon, skin.id])));
const byId = new Map(SKINS.map(skin => [skin.id, skin]));
export function getSkin(id) { return typeof id === 'string' ? byId.get(id) : undefined; }
export function normalizeSkinLoadout(input = {}) {
  const value = input && typeof input === 'object' && !Array.isArray(input) ? input : {};
  return Object.fromEntries(Object.entries(DEFAULT_SKINS).map(([weapon, fallback]) => {
    const candidate = getSkin(value[weapon]);
    return [weapon, candidate?.weapon === weapon ? candidate.id : fallback];
  }));
}
